{
  "findings": [
    {
      "check_id": "CKV_AWS_355",
      "title": "IAM policy allows wildcard resource for SageMaker actions",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "MEDIUM",
      "explanation": "The IAM policy grants 'sagemaker:CreatePresignedNotebookInstanceUrl' and 'sagemaker:ListNotebookInstances' on all resources ('*'). This violates the principle of least privilege, allowing access to any SageMaker notebook instance in the account rather than restricting it to specific instances."
    }
  ],
  "patched_code": "resource "aws_iam_policy" "privesc-sageMakerCreatePresignedNotebookURL-policy" {
  name        = "privesc-sageMakerCreatePresignedNotebookURL-policy"
  path        = "/"
  description = "Allows privesc via sagemakerCreatePresignedNotebookURL"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action = [
          "sagemaker:CreatePresignedNotebookInstanceUrl",
          "sagemaker:ListNotebookInstances"
        ]
        Resource = "arn:aws:sagemaker:*:*:notebook-instance/*"
      },
    ]
  })
}",
  "fix_summary": "Replaced the wildcard '*' in the Resource field with a more restrictive ARN pattern 'arn:aws:sagemaker:*:*:notebook-instance/*' to limit permissions specifically to SageMaker notebook instances, addressing the over-permissive resource scope."
}
